// ---- assets: bundle our MIT Fluent icons + gpui-component's own assets -------

#[derive(RustEmbed)]
#[folder = "assets/icons"]
#[prefix = "icons/"]
struct Icons;

/// Serves our embedded Fluent icon SVGs (`icons/*.svg`), falling back to
/// gpui-component's bundled assets for everything else.
struct DocxyAssets;
impl AssetSource for DocxyAssets {
    fn load(&self, path: &str) -> gpui::Result<Option<Cow<'static, [u8]>>> {
        if let Some(f) = Icons::get(path) {
            return Ok(Some(f.data));
        }
        gpui_component_assets::Assets.load(path)
    }
    fn list(&self, path: &str) -> gpui::Result<Vec<SharedString>> {
        gpui_component_assets::Assets.list(path)
    }
}

fn icon_svg(name: &str, size: f32, color: Hsla) -> Svg {
    svg()
        .path(SharedString::from(format!("icons/{name}.svg")))
        .size(px(size))
        .text_color(color)
        .flex_none()
}

/// The editor a tab's keystrokes and commands drive: its header/footer
/// editor while one is open, else a document's body; none on other tabs.
fn tab_edit_target(tab: &mut DocTab) -> Option<&mut Editor> {
    if let Some(hf) = tab.hf_edit.as_mut() {
        return Some(&mut hf.editor);
    }
    match &mut tab.surface {
        Surface::Doc(ed) => Some(ed),
        _ => None,
    }
}

/// [`tab_edit_target`], to read.
fn tab_edit_target_ref(tab: &DocTab) -> Option<&Editor> {
    if let Some(hf) = tab.hf_edit.as_ref() {
        return Some(&hf.editor);
    }
    match &tab.surface {
        Surface::Doc(ed) => Some(ed),
        _ => None,
    }
}

/// A small Quick-Access-Toolbar icon button (Undo/Redo in the title bar).
/// A disabled one (Can't Repeat, #618) is drawn dimmed and takes no click.
fn qat_btn(
    id: &'static str,
    icon: &'static str,
    tip: &'static str,
    enabled: bool,
    pal: Pal,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
) -> Stateful<Div> {
    let btn = div()
        .id(id)
        .flex()
        .items_center()
        .justify_center()
        .size(px(20.))
        .rounded(px(3.))
        .tooltip(move |w, cx| Tooltip::new(tip).build(w, cx));
    if !enabled {
        return btn.child(icon_svg(icon, 14., pal.dim));
    }
    btn.cursor_pointer()
        .hover(|d| d.bg(pal.hover))
        .active(|d| d.bg(Hsla { a: 0.22, ..pal.fg }))
        .child(icon_svg(icon, 14., pal.fg))
        .on_click(on_click)
}

/// Where the Undo drop-down opens: below the arrow, when the last frame drew
/// it.
fn qat_undo_anchor(probes: &Probes) -> Option<Point<Pixels>> {
    probes.current("qat-undo-arrow").map(|b| b.bottom_left())
}

// ---- session model ---------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Serialize, Deserialize)]
enum Kind {
    Project,
    Docx,
    Xlsx,
    Look,
}

impl Kind {
    fn glyph(self) -> &'static str {
        match self {
            Kind::Project => "\u{1F4C5}",
            Kind::Docx => "\u{1F4C4}",
            Kind::Xlsx => "\u{1F4CA}",
            Kind::Look => "\u{2709}",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, Default)]
enum ThemePref {
    #[default]
    Auto,
    Light,
    Dark,
}

impl ThemePref {
    fn resolve(self, appearance: gpui::WindowAppearance) -> ThemeMode {
        match self {
            ThemePref::Auto => ThemeMode::from(appearance),
            ThemePref::Light => ThemeMode::Light,
            ThemePref::Dark => ThemeMode::Dark,
        }
    }
    fn label(self) -> &'static str {
        match self {
            ThemePref::Auto => "\u{25D1} Auto",
            ThemePref::Light => "\u{2600} Light",
            ThemePref::Dark => "\u{263D} Dark",
        }
    }
    fn next(self) -> Self {
        match self {
            ThemePref::Auto => ThemePref::Light,
            ThemePref::Light => ThemePref::Dark,
            ThemePref::Dark => ThemePref::Auto,
        }
    }
}

#[derive(Clone, Serialize, Deserialize)]
struct PersistTab {
    kind: Kind,
    title: String,
    path: Option<String>,
    #[serde(default)]
    dirty: bool,
    /// Hot-exit sidecar holding this tab's current (possibly unsaved) content,
    /// in the format matching its kind: `.docx`, `.xlsx`, or `.yppx`.
    /// Restored in preference to `path` so edits survive a restart.
    #[serde(default)]
    hot: Option<String>,
    /// Names omitted from a project hot-exit sidecar because their ZIP entries
    /// could not be read. Restore them before allowing a later Save.
    #[serde(default)]
    unreadable: Vec<String>,
    #[serde(default)]
    markdown: bool,
    /// The tab's file could not be loaded, so `hot` holds a placeholder and
    /// Save must not write it back over `path` (#209). `None` in a session
    /// written before this was recorded: restore then asks the file itself.
    #[serde(default)]
    load_failed: Option<bool>,
    /// The tab's [`open_mode::Access`] (#610), so a read-only, repaired or
    /// Protected View tab comes back the same. Protected View is kept, never
    /// re-read from the file's zone: that would undo Enable Editing.
    #[serde(default)]
    read_only: bool,
    #[serde(default)]
    protected: bool,
    #[serde(default)]
    repaired: bool,
    /// A protected tab's file as it was opened (#882), for Enable Editing
    /// after a restart.
    #[serde(default)]
    stamp: Option<trusted::Stamp>,
    /// What a document tab was converted from (#633): its sidecar is a
    /// `.docx`, but `path` still names the RTF, page, PDF or damaged file,
    /// which Save must never write.
    #[serde(default)]
    converted: Option<open_mode::Converted>,
    /// The document's [`doc_import::DocImport`] (#634). A dirty tab restores
    /// from its `.docx` sidecar, which says neither, so without these its
    /// Save would write over the `.doc` it was imported from.
    #[serde(default)]
    binary_source: bool,
    #[serde(default)]
    compat: bool,
}

#[derive(Serialize, Deserialize)]
struct Session {
    tabs: Vec<PersistTab>,
    active: usize,
    #[serde(default)]
    theme: ThemePref,
    #[serde(default)]
    ask_on_close: bool,
    /// Minutes between AutoRecover writes while a tab is unsaved; 0 is off.
    /// A session written before the setting existed gets Word's 10.
    #[serde(default = "autorecover_default")]
    autorecover_minutes: u32,
    /// Excel's "Keep the last AutoRecovered version if I close without
    /// saving" (#613). A session written before the setting gets Excel's on.
    #[serde(default = "keep_drafts_default")]
    keep_drafts: bool,
    /// File › Options › Advanced › Editing for sheet tabs (#672), as the
    /// `key=value` lines `EditOptions` writes: the reader xlsxy uses too, so
    /// a session written before the setting (or a bad value) gets Excel's
    /// defaults.
    #[serde(default)]
    sheet_editing: String,
    /// File › Options › General › "Personalize your copy": the name and
    /// initials new comments are stamped with (#620). Empty means the OS
    /// account name and the initials derived from it ([`review_identity`]).
    #[serde(default)]
    user_name: String,
    #[serde(default)]
    user_initials: String,
}

fn autorecover_default() -> u32 {
    recover::DEFAULT_MINUTES
}

fn keep_drafts_default() -> bool {
    true
}

/// The status of a tab opened from Recover Unsaved Workbooks (#613).
const DRAFT_OPENED: &str = "recovered unsaved workbook — read-only; use Save As to keep it";

/// Whether a tab just opened from a draft gets [`DRAFT_OPENED`]: only when the
/// workbook loaded. An unreadable draft opens as a placeholder whose load
/// error must stay its status.
fn draft_loaded(tab: &DocTab) -> bool {
    matches!(tab.surface, Surface::Sheet(_))
}

// Not derived: a fresh install (no session.json) must get AutoRecover on, not 0.
impl Default for Session {
    fn default() -> Self {
        Self {
            tabs: Vec::new(),
            active: 0,
            theme: ThemePref::default(),
            ask_on_close: false,
            autorecover_minutes: recover::DEFAULT_MINUTES,
            keep_drafts: true,
            sheet_editing: String::new(),
            user_name: String::new(),
            user_initials: String::new(),
        }
    }
}

/// The settings `session.json` carries besides the tabs.
#[derive(Clone)]
struct Prefs {
    theme: ThemePref,
    ask_on_close: bool,
    autorecover_minutes: u32,
    keep_drafts: bool,
    edit_opts: EditOptions,
    /// File › Options › Advanced › Edit Custom Lists (#668), saved with the
    /// editing options in `sheet_editing`.
    custom_lists: Vec<Vec<String>>,
    /// AutoCorrect's changes from its defaults (#667), as
    /// [`gridcore::autocorrect::AutoCorrect::to_lines`] writes them; saved
    /// in `sheet_editing` with the Editing options.
    autocorrect: String,
    user_name: String,
    user_initials: String,
}

/// Environment variable that redirects every file the app persists — the
/// session, the hot sidecars, and (later) the harness discovery file — to a
/// directory of the caller's choosing. Set by the UI test harness so a test
/// instance cannot touch the installed app's state.
const CONFIG_DIR_ENV: &str = "DOCXY_CONFIG_DIR";

/// Root under which everything this app persists lives. Normally the OS config
/// directory; a `DOCXY_CONFIG_DIR` override redirects all of it at once.
///
/// ⚠️ The override has to be its own variable rather than `APPDATA`. Measured on
/// Windows 11 with `APPDATA` pointed elsewhere: `ctlcore::config_ctl_dir` reads
/// `APPDATA` and follows the override, while `dirs::config_dir()` asks the
/// known-folder API and keeps returning the real `…\AppData\Roaming`. So an
/// `APPDATA` override moves the control socket but leaves `session.json` and
/// the hot sidecars in the user's own profile — isolation that looks complete
/// and is not. One explicit variable that BOTH path mechanisms go through is
/// the only thing that actually isolates.
fn config_root() -> PathBuf {
    config_root_from(std::env::var_os(CONFIG_DIR_ENV), dirs::config_dir())
}

/// The decision behind [`config_root`], separated from the environment so it
/// can be tested. An override that is set but empty counts as unset — an
/// exported-but-blank variable is a shell accident, not a request to write into
/// the current directory. A relative override is honoured verbatim (resolved
/// against the working directory), because that is what typing one means.
fn config_root_from(over: Option<std::ffi::OsString>, os_config: Option<PathBuf>) -> PathBuf {
    match over {
        Some(v) if !v.is_empty() => PathBuf::from(v),
        _ => os_config.unwrap_or_else(|| PathBuf::from(".")),
    }
}

fn session_path_in(root: &std::path::Path) -> PathBuf {
    root.join("docxy").join("session.json")
}

